// src/types/token.ts
import { isAddressEqual } from "viem";
var TokenInfo = class {
  address;
  name;
  symbol;
  decimals;
  logoURI;
  abi;
  constructor(props) {
    return Object.assign(this, props);
  }
  /**
   * Checks whether the object is equal to o
   * @param o - The other object
   */
  isEqual(o) {
    if (!this.address || !o.address)
      return false;
    return isAddressEqual(
      this.address,
      o.address
    );
  }
};

